const meta = $('Resolve Client').first().json || {};
const NO_CLIENT = '00000000-0000-0000-0000-000000000000';
const BISON = '00000000-0000-4000-a000-000000000002';
const AIMFOX = '00000000-0000-4000-a000-000000000003';
const s = v => { const t = String(v ?? '').trim(); return t === '' ? null : t; };
const bool = v => /^(true|yes|tak|1|x|✓|v|done|y)$/i.test(String(v ?? '').trim());
const pad = n => String(n).padStart(2, '0');
// Client sheets use different date locales. Detect the order from the whole tab
// (a value > 12 in one position settles it) instead of assuming D/M/Y per row.
const detectOrder = vals => {
  let dmy = 0, mdy = 0;
  for (const v of vals) {
    let m = String(v ?? '').trim().match(/^(\d{1,2})[./](\d{1,2})[./]\d{4}/);
    if (m) { if (Number(m[1]) > 12) dmy++; if (Number(m[2]) > 12) mdy++; continue; }
    m = String(v ?? '').trim().match(/^\d{4}-(\d{1,2})-(\d{1,2})/);
    if (m) { if (Number(m[2]) > 12) dmy++; if (Number(m[1]) > 12) mdy++; }
  }
  return mdy > dmy ? 'mdy' : 'dmy';
};
const isoDate = (v, order) => {
  const t = String(v ?? '').trim();
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) { let a = Number(m[2]), b = Number(m[3]);
    let mo = order === 'mdy' ? a : (a > 12 ? b : a);
    let d  = order === 'mdy' ? b : (a > 12 ? a : b);
    if (mo > 12) { const t2 = mo; mo = d; d = t2; }
    return (mo >= 1 && mo <= 12 && d >= 1 && d <= 31) ? `${m[1]}-${pad(mo)}-${pad(d)}` : null; }
  m = t.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})/);
  if (m) { let d = Number(m[1]), mo = Number(m[2]);
    if (order === 'mdy') { const t2 = d; d = mo; mo = t2; }
    if (mo > 12 && d <= 12) { const t2 = mo; mo = d; d = t2; }
    return (mo >= 1 && mo <= 12 && d >= 1 && d <= 31) ? `${m[3]}-${pad(mo)}-${pad(d)}` : null; }
  return null;
};
const qual = v => { const t = String(v ?? '').trim().toLowerCase();
  if (t === 'mql') return 'MQL'; if (t === 'premql') return 'preMQL'; return null; };
const order = detectOrder($input.all().map(i => (i.json || {})['LEAD RECEIVED']));
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || (j.message && Object.keys(j).length <= 3)) continue;
  if (!j['E-MAIL'] && !j['FULL NAME'] && !j['LEAD RECEIVED']) continue;
  const full = s(j['FULL NAME']) || '';
  const parts = full.split(/\s+/).filter(Boolean);
  const cid = s(j['Campaign ID']);
  const isAimfox = !!cid && /^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(cid);
  rows.push({
    email: s(j['E-MAIL']), first_name: parts[0] || null,
    last_name: parts.length > 1 ? parts.slice(1).join(' ') : null,
    job_title: s(j['JOB TITLE']), company_name: s(j['COMPANY NAME']),
    website: s(j['WEBSITE']), industry: s(j['INDUSTRY']), headcount: s(j['HEADCOUNT']),
    phone: s(j['Phone Number']), phone_source: s(j['Phone Source']),
    linkedin: s(j['LinkedIn URL']), country: s(j['Column 29']),
    message_title: s(j['MESSAGE TITLE']),
    qualification: qual(j['QUALIFICATION']),
    meeting_booked: bool(j['MEETINGS']), meeting_held: bool(j['MEETINGS HELD']),
    offer_sent: bool(j['OFFER SENT']), won: bool(j['WON']),
    reply_text: s(j['Mail from lead']), client_note: s(j['COMMENTS']),
    campaign_external_id: isAimfox ? null : cid,
    lead_received: isoDate(j['LEAD RECEIVED'], order),
    sequencer_id: isAimfox ? AIMFOX : BISON,
  });
}
if (!meta.client_id) return [{ json: { client_id: NO_CLIENT, client: (meta.name || $('Loop Over Items').first().json.client || 'unresolved'), sheet_rows: 0, date_order: 'n/a', payload: '[]' } }];
return [{ json: { client_id: meta.client_id, client: meta.name, sheet_rows: rows.length, date_order: order, payload: JSON.stringify(rows) } }];

const out = [];
for (const i of $input.all()) {
  const j = i.json;
  const doc = String(j.col_4 ?? '').trim();
  const ws  = String(j.col_5 ?? '').trim();
  const name = String(j['Customer Success'] ?? '').trim();
  if (!doc || doc.length < 30 || !ws) continue;
  out.push({ json: { client: name, ws, doc } });
}
return out;
